package org.privacyguides.verifiedapps

import org.privacyguides.verifiedapps.data.Hashes


enum class Source(val displayName: String) {
    NONE("NONE"), // DO NOT USE IN DATABASE ENTRIES.
    ACCRESCENT("Accrescent"),
    APPVERIFIER("AppVerifier"),
    APP_FDROID_REPO("App's F-Droid Repo"),
    CODEBERG("Codeberg"),
    CUSTOM_APKPURE("Custom (APKPure)"),
    CUSTOM_GRAPHENEOS_APP_STORE("Custom (GrapheneOS App Store)"),
    CUSTOM_SAMSUNG("Custom (Samsung)"),
    DIRECT_APK_LINK("Direct APK Link"),
    DNS_VERIFIED_DOMAIN("DNS Verified Domain"),
    FDROID("F-Droid"),
    FDROID_IZZYONDROID("F-Droid (IzzyOnDroid)"),
    F_DROID_APP_FUTO_ORG("F-Droid (app.futo.org)"),
    F_DROID_APP_SIMPLEX_CHAT("F-Droid (app.simplex.chat)"),
    F_DROID_ARCHIVE_NEWPIPE_NET("F-Droid (archive.newpipe.net)"),
    F_DROID_BRIARPROJECT_ORG("F-Droid (briarproject.org)"),
    F_DROID_FDROID_EMERSION_FR("F-Droid (fdroid.emersion.fr)"),
    F_DROID_FDROID_STORCHP_DE("F-Droid (fdroid.storchp.de)"),
    F_DROID_FDROID_TYPEBLOG_NET("F-Droid (fdroid.typeblog.net)"),
    F_DROID_GROBOX_DE("F-Droid (grobox.de)"),
    F_DROID_MOBILEAPP_BITWARDEN_COM("F-Droid (mobileapp.bitwarden.com)"),
    F_DROID_PRIVACYGUIDES_GITHUB_IO("F-Droid (privacyguides.github.io)"),
    GITHUB("GitHub"),
    GITLAB("GitLab"),
    GOOGLE_PIXEL_OS("Google Pixel OS"),
    GOOGLE_PLAY_STORE("Google Play"),
    HTTPS_VERIFIED_DOMAIN("HTTPS Verified Domain"),
    VERIFIED_APPS("Verified Apps"),
    WEBSITE("App's Website"),
}

/**
 * The package name is the app's package name.
 *
 * The hashesList is a list of Hashes, which itself contains a list of hashes.
 *
 * The hasMultipleSigners (the true or false) is whether it has multiple signers or not.
 * hasMultipleSigners can be viewed from the app by turning on the relevant setting.
 *
 * There should be one Hashes for each signing configuration an app has.
 * The Hashes has a sources value.
 * For example, if those Hashes are from both GitHub and the Google Play Store (you checked and both have the same
 * hashes),
 * then the database entry would be:
 *
 * ```
 * InternalDatabaseVerificationInfo(
 *     "com.example.app",
 *     listOf(
 *         Hashes(
 *             listOf(
 *                 Source.GITHUB,
 *                 Source.GOOGLE_PLAY_STORE
 *             ),
 *             listOf(
 *                 "SOME HASH HERE",
 *                 "ANOTHER HASH HERE"
 *             ),
 *             false
 *         )
 *     )
 * ),
 * ```
 *
 * If for example the Google Play Store one has different hashes then it gets its own Hashes
 * with sources that has only Google Play Store like below:
 *
 * ```
 * InternalDatabaseVerificationInfo(
 *     "com.example.app",
 *     listOf(
 *         Hashes(
 *             listOf(
 *                 Source.GITHUB
 *             ),
 *             listOf(
 *                 "SOME HASH HERE",
 *                 "ANOTHER HASH HERE"
 *             ),
 *             false
 *         )
 *         Hashes(
 *             listOf(
 *                 Source.GOOGLE_PLAY_STORE
 *             ),
 *             listOf(
 *                 "SOME DIFFERENT HASH HERE",
 *                 "ANOTHER DIFFERENT HASH HERE"
 *             ),
 *             false
 *         )
 *     )
 * ),
 * ```
 */
data class InternalDatabaseVerificationInfo(
    val packageName: String,
    val hashesList: List<Hashes>
)

